#[path = "common/command.rs"] mod commands;
#[path = "common/mod.rs"] mod common;
use commands::command;
use std::{collections::BTreeMap, fs, path::{Path, PathBuf}, time::{SystemTime, UNIX_EPOCH}};
fn run(p: &Path, program: &str, args: &[&str], code: i32, line: &str) -> String {
    let o = command(p, program, args).output().unwrap(); let s = format!("{}{}", String::from_utf8_lossy(&o.stdout), String::from_utf8_lossy(&o.stderr));
    assert_eq!(o.status.code(), Some(code), "{args:?}: {s}"); assert!(s.contains(line), "{args:?}: {s}"); s
}
fn git(p: &Path, args: &[&str]) { run(p, "git", args, 0, ""); }
fn cli(p: &Path, args: &[&str], code: i32, line: &str) { run(p, env!("CARGO_BIN_EXE_whosaidso"), args, code, line); }
fn write(p: &Path, s: &str) { fs::create_dir_all(p.parent().unwrap()).unwrap(); fs::write(p, s).unwrap(); }
fn commit(p: &Path, msg: &str) { git(p, &["add", "-A"]); git(p, &["commit", "-m", msg, "-m", "Goal: none"]); }
fn records(p: &Path, kind: &str) -> BTreeMap<PathBuf, Vec<u8>> { let mut r = BTreeMap::new(); let d = p.join(".whosaidso").join(kind); if d.exists() { for e in fs::read_dir(d).unwrap() { let e = e.unwrap(); if e.path().extension().is_some_and(|x| x == "json") { r.insert(e.path(), fs::read(e.path()).unwrap()); } } } r }
fn keep(r: &BTreeMap<PathBuf, Vec<u8>>) { for (p, b) in r { assert_eq!(&fs::read(p).unwrap(), b, "{}", p.display()); } }
fn state(p: &Path, expected: Option<&str>) { let s = run(p, env!("CARGO_BIN_EXE_whosaidso"), &["goals"], 0, "done"); match expected { Some(x) => assert!(s.lines().any(|l| l.split_whitespace().collect::<Vec<_>>().windows(2).any(|w| w == [x, "goal"])), "{s}"), None => assert!(!s.lines().any(|l| l.split_whitespace().any(|w| w == "goal")), "{s}") } }
#[test]
fn records_survive_lifecycle_and_prune() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).join("target/e2e-tmp").join(format!("wss-records-{}-{}", std::process::id(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos())); fs::create_dir_all(&root).unwrap(); git(&root, &["init", "--bare", "origin.git"]); git(&root, &["clone", "origin.git", "work"]); let p = root.join("work");
    write(&p.join(".whosaidso/phases/p.json"), "{\"title\":\"Phase\",\"order\":1}\n"); write(&p.join(".whosaidso/goals/goal.json"), "{\"title\":\"Goal\",\"done_when\":\"works\",\"check\":\"test\",\"broader\":\"p\"}\n"); write(&p.join(".whosaidso/instruments/test.json"), "{\"run\":[\"sh\",\"test.sh\"],\"answers\":\"works\"}\n"); write(&p.join("test.sh"), "#!/bin/sh\nexit 0\n"); commit(&p, "records"); git(&p, &["push", "-u", "origin", "main"]); state(&p, Some("open"));
    cli(&p, &["prove", "goal"], 0, "prove: goal pass"); commit(&p, "proof"); state(&p, Some("done")); let old = records(&p, "proofs"); assert_eq!(old.len(), 1);
    fs::remove_file(p.join(".whosaidso/goals/goal.json")).unwrap(); state(&p, None); cli(&p, &["prune"], 1, "prune: commit or stash your .whosaidso changes first"); keep(&old); git(&p, &["restore", ".whosaidso/goals/goal.json"]); state(&p, Some("done")); cli(&p, &["prune"], 0, "prune: 0 proofs, 0 asks, 0 media archived"); state(&p, Some("done")); keep(&old);
    fs::remove_file(p.join(".whosaidso/goals/goal.json")).unwrap(); commit(&p, "retire goal"); state(&p, None); cli(&p, &["prune"], 0, "prune: 1 proofs, 0 asks, 0 media archived"); state(&p, None); assert!(old.keys().all(|x| !x.exists())); commit(&p, "prune retired goal"); git(&p, &["restore", "--source=HEAD~2", ".whosaidso/goals/goal.json", ".whosaidso/instruments/test.json", ".whosaidso/proofs"]); commit(&p, "restore goal and evidence"); state(&p, Some("done")); keep(&old); cli(&p, &["prune"], 0, "prune: 0 proofs, 0 asks, 0 media archived"); state(&p, Some("done")); keep(&old);
    write(&p.join(".whosaidso/instruments/test.json"), "{\"run\":[\"sh\",\"test.sh\",\"new\"],\"answers\":\"updated\"}\n"); commit(&p, "replace instrument"); state(&p, Some("open")); cli(&p, &["prove", "goal"], 0, "prove: goal pass"); commit(&p, "new proof"); state(&p, Some("done")); let all = records(&p, "proofs"); let new: BTreeMap<_, _> = all.into_iter().filter(|(k, _)| !old.contains_key(k)).collect(); assert_eq!(new.len(), 1); cli(&p, &["prune"], 0, "prune: 1 proofs, 0 asks, 0 media archived"); state(&p, Some("done")); keep(&new); commit(&p, "prune old proof");
    let mut previous = records(&p, "asks");
    for i in 0..6 { cli(&p, &["ask", "goal", &format!("question-{i}")], 0, "ask: goal "); state(&p, Some("done")); keep(&new); keep(&previous); let current = records(&p, "asks"); assert_eq!(current.len(), i + 1); previous = current; }
    let asks = records(&p, "asks"); assert_eq!(asks.len(), 6); commit(&p, "asks"); cli(&p, &["prune"], 0, "prune: 0 proofs, 1 asks, 0 media archived"); state(&p, Some("done")); keep(&new); let kept_asks = records(&p, "asks"); assert_eq!(kept_asks.len(), 5); for (k, v) in &kept_asks { assert_eq!(asks.get(k), Some(v)); } assert!(kept_asks.values().all(|b| !String::from_utf8_lossy(b).contains("question-0"))); commit(&p, "prune asks");
    let mut previous = records(&p, "media");
    for i in 0..101 { let image = root.join(format!("{i}.png")); fs::write(&image, common::png(format!("image-{i}"))).unwrap(); cli(&p, &["media", "goal", image.to_str().unwrap(), &format!("image-{i}")], 0, "media: goal "); state(&p, Some("done")); keep(&new); keep(&kept_asks); keep(&previous); let current = records(&p, "media"); assert_eq!(current.len(), i + 1); previous = current; }
    let media = records(&p, "media"); assert_eq!(media.len(), 101); commit(&p, "media"); cli(&p, &["prune"], 0, "prune: 0 proofs, 0 asks, 1 media archived"); state(&p, Some("done")); keep(&new); keep(&kept_asks); let kept_media = records(&p, "media"); assert_eq!(kept_media.len(), 100); for (k, v) in &kept_media { assert_eq!(media.get(k), Some(v)); let j: serde_json::Value = serde_json::from_slice(v).unwrap(); let hash = j["media_sha256"].as_str().unwrap(); let blob = p.join(".git/whosaidso/blobs").join(format!("{hash}.{}", j["ext"].as_str().unwrap())); let index = j["shows"].as_str().unwrap().strip_prefix("image-").unwrap(); assert_eq!(fs::read(blob).unwrap(), common::png(format!("image-{index}"))); } assert!(kept_media.values().all(|b| !String::from_utf8_lossy(b).contains("image-0"))); let retired: Vec<_> = media.iter().filter(|(path, _)| !kept_media.contains_key(*path)).collect(); assert_eq!(retired.len(), 1);
    let archive = p.join(".git/whosaidso/archive"); let bundle = fs::read_dir(&archive).unwrap().map(|e| e.unwrap().path()).find(|x| x.extension().is_some_and(|x| x == "tar")).unwrap();
    let extracted = root.join("extracted"); fs::create_dir(&extracted).unwrap(); run(&extracted, "tar", &["-xf", bundle.to_str().unwrap()], 0, "");
    for (path, bytes) in retired { let id = path.file_stem().unwrap().to_str().unwrap(); assert_eq!(fs::read(extracted.join(format!("{id}.json"))).unwrap(), *bytes); assert_eq!(fs::read(extracted.join(format!("{id}.png"))).unwrap(), common::png("image-0")); }
    commit(&p, "prune media"); git(&p, &["push"]); fs::remove_dir_all(root).unwrap();
}
